  "track.coroutines.m.chan.s.buffered.title": "send({v}): into the buffer",
  "track.coroutines.m.chan.s.buffered.explain": "The buffer has room, so `send` returns immediately and the element waits in the channel (buffer: {n}).",
  "track.coroutines.m.chan.ev.buffered": "send({v}): into the buffer",
  "track.coroutines.m.chan.s.full.title": "send({v}): suspends, no room",
  "track.coroutines.m.chan.s.full.explain": "There is no room (the buffer is full, or RENDEZVOUS has no buffer) and nobody is waiting to receive, so the producer suspends right at `send`.",
  "track.coroutines.m.chan.ev.full": "send({v}): suspends, no room",
  "track.coroutines.m.chan.s.resumed.title": "Room appears: the producer resumes, {v} enters the buffer",
  "track.coroutines.m.chan.s.resumed.explain": "The consumer just took an element, so the waiting `send` completes.",
  "track.coroutines.m.chan.ev.resumed": "Room appears: the producer resumes, {v} enters the buffer",
  "track.coroutines.m.chan.s.handover.title": "Rendezvous: {v} handed straight to the consumer",
  "track.coroutines.m.chan.s.handover.explain": "The consumer arrives while the producer waits at `send`: the element goes straight from sender to receiver, and the producer resumes.",
  "track.coroutines.m.chan.ev.handover": "Rendezvous: {v} handed straight to the consumer",
  "track.coroutines.m.chan.s.sentLine.title": "the producer prints \"Sent\"",
  "track.coroutines.m.chan.s.sentLine.explain": "After `delay(100)`, the producer prints \"Sent\" and moves on to the next element.",
