  "track.coroutines.m.chan.s.closed.title": "produce finishes: the channel closes",
  "track.coroutines.m.chan.s.closed.explain": "`produce` calls `close()` on the channel itself when its block ends, so the consumer's `for` loop stops after draining it.",
  "track.coroutines.m.chan.ev.closed": "produce finishes: the channel closes",
  "track.coroutines.m.chan.s.got.title": "the consumer receives {v}",
